styles.tutorial:
section[data-skill-hub] .-w {
  position: relative;
  padding-top: calc( var(--vh,1vh) * 25 );
  padding-bottom: calc( var(--vh,1vh) * 80 );
}

section[data-skill-hub] .sentence-1 {}
section[data-skill-hub] .sentence-1 .-s-word[data-split-content="Into"] {
  margin-left: 1em;
}
section[data-skill-hub] .sentence-1 .-s-word[data-split-content="Every"] {
  margin-left: 1em;
}
section[data-skill-hub] .sentence-1 .-s-word[data-split-content="Line."] {
  margin-left: 2em;
}

section[data-skill-hub] .sentence-2 {}
section[data-skill-hub] .sentence-2 .-s-word[data-split-content="Precision,"] {
  margin-left: 4em;
}
section[data-skill-hub] .sentence-2 .-s-word[data-split-content="Carried"] {
  margin-left: 1em;
}
section[data-skill-hub] .sentence-2 .-s-word[data-split-content="In"] {
  margin-left: 3em;
}
section[data-skill-hub] .sentence-2 .-s-word[data-split-content="Cut."] {
  margin-left: 1em;
}

section[data-skill-hub] .sentence-3 {}
section[data-skill-hub] .sentence-3 .-s-word[data-split-content="Before"] {
  margin-left: 1em;
}
section[data-skill-hub] .sentence-3 .-s-word[data-split-content="It’s"] {
  margin-left: 1em;
}
section[data-skill-hub] .sentence-3 .-s-word[data-split-content="Seen."] {
  margin-left: 4em;
}


section[data-skill-hub] .-s-line {
  width: 100%;
}
section[data-skill-hub] .-s-char {
  --area: 0.15em;
  position: relative;
  overflow: hidden;
  padding: 0 0 var(--area) 0;
  margin: 0 0 calc(-1 * var(--area)) 0;
  color: transparent;


  --char-turn: calc( var(--char-random) / var(--char-global-total) );

  --char-step: calc( 1 / var(--char-global-total) );
  --char-progress: clamp( 0, calc( (var(--progress) - var(--char-turn)) / var(--char-step) ), 1 );
}
section[data-skill-hub] .-s-char::before {
  content: attr(data-split-content);
  position: absolute;
  inset: 0;
  padding: 0 0 var(--area) 0;
  color: #E1B1AB;

  transform: translate3d(calc(var(--char-progress) * 50% ), 0, 0);
  opacity: calc( 1 - var(--char-progress) );
}
section[data-skill-hub] .-s-char::after {
  content: attr(data-split-content);
  position: absolute;
  inset: 0;
  padding: 0 0 var(--area) 0;
  color: #E1B1AB;

  transform: translate3d(calc(-100% + var(--char-progress) * 100% ), 0, 0);
}



@media (min-width: 1024px) {
  section[data-skill-hub] .sentence-1 {
    margin-left: calc( var(--col) + var(--g-gap) );
  }
  section[data-skill-hub] .sentence-2 {
    margin-left: calc( var(--col) * 4 + var(--g-gap) * 3 );
  }
  section[data-skill-hub] .sentence-3 {
    margin-left: calc( var(--col) + var(--g-gap) );
  }
  section[data-skill-hub] .-s-line {
    translate: 0 calc( 100% * var(--progress) );
  }
}
